#define REG_ACCESS_CHECK() \
    do { \
        if (!g_bq25710_ctx.initialized) return BQ25710_ERR_NOT_INIT; \
        if (!g_bq25710_ctx.smbus_read || !g_bq25710_ctx.smbus_write) \
            return BQ25710_ERR_I2C; \
    } while (0)

#define PARAM_CHECK(cond) \
    do { if (!(cond)) return BQ25710_ERR_PARAM; } while (0)

/**
 * @brief 检查指针是否为 NULL 宏
 * @param ptr 指针变量
 * @return 错误码
 */
#define NULL_CHECK(ptr)                                                        \
  do {                                                                         \
    if (!(ptr))                                                                \
      return BQ25710_ERR_NULL_PTR;                                             \
  } while (0)

/**
 * @brief 判断电池类型宏
 * @param chemistry 化学类型
 * @return 错误码
 */
#define IS_BATTERY_TYPE(chemistry)                                             \
  do {                                                                         \
    if (((chemistry) != BATTERY_CHEM_LIFEPO4) &&                               \
        ((chemistry) != BATTERY_CHEM_NMC) &&                                   \
        ((chemistry) != BATTERY_CHEM_LIPO) &&                                  \
        ((chemistry) != BATTERY_CHEM_LCO) &&                                   \
        ((chemistry) != BATTERY_CHEM_LTO))                                     \
      return BQ25710_ERR_PARAM;                                                \
  } while (0)

/**
 * @brief 判断电池节数宏
 * @param cells 串联节数
 * @return 错误码
 */
#define IS_BATTERY_CELLS(cells)                                                \
  do {                                                                         \
    if (((cells) < BATTERY_CELLS_1S) || ((cells) > BATTERY_CELLS_4S))          \
      return BQ25710_ERR_PARAM;                                                \
  } while (0)


/* SMBus 7-bit 地址: BQ25710 默认 0x09 (左移一位为 0x12) */
#define BQ25710_SMBUS_ADDR  0x09

/**
 * @brief 读取寄存器 (SMBus Read-Word)
 * @param reg   寄存器地址
 * @param value 输出参数
 * @return 0=成功
 */
static int8_t _reg_read(uint8_t reg, uint16_t *value)
{
    return g_bq25710_ctx.smbus_read(reg, value);
}

/**
 * @brief 写入寄存器 (SMBus Write-Word)
 * @param reg   寄存器地址
 * @param value 要写入的值
 * @return 0=成功
 */
static int8_t _reg_write(uint8_t reg, uint16_t value)
{
    return g_bq25710_ctx.smbus_write(reg, value);
}

/**
 * @brief 读-修改-写寄存器
 * @param reg       寄存器地址
 * @param mask      要修改的位掩码
 * @param new_bits  新的位值 (已对齐到 mask 位置)
 * @return 0=成功
 */
static int8_t _reg_rmw(uint8_t reg, uint16_t mask, uint16_t new_bits)
{
    uint16_t val;
    int8_t ret;

    ret = _reg_read(reg, &val);
    if (ret != 0) return BQ25710_ERR_I2C;

    val = (val & ~mask) | (new_bits & mask);

    ret = _reg_write(reg, val);
    if (ret != 0) return BQ25710_ERR_I2C;

    return BQ25710_ERR_OK;
}

/**
 * @brief 通用步进参数校验
 * 
 * @param value   待校验的值
 * @param min_val 最小允许值
 * @param max_val 最大允许值
 * @param step    步进值
 * @return int8_t 状态码
 */
static int8_t validate_step(uint16_t value, uint16_t min_val, uint16_t max_val, uint16_t step)
{
    if ((value < min_val) || 
        (value > max_val) ||
        ((value % step) != 0)) 
    {
        return BQ25710_ERR_PARAM;
    }
    return BQ25710_ERR_OK;
}
