/* =========================================================================
 * 电池参数查找表 (8 组: 2 化学类型 × 4 节数)
 *
 * 寄存器计算公式 (注释中标明):
 *   MaxChargeVoltage:  reg = (总电压_mV / 8) << 3  [LSB=8mV, 偏移3bit]
 *   MinSystemVoltage:  reg = (电压_mV / 256) << 8  [LSB=256mV, 偏移8bit]
 *   ChargeCurrent:     reg = (电流_mA / 64) << 6   [LSB=64mA, 偏移6bit]
 *
 * LiFePO4: 单节终止 3.60V, 平台 3.2V
 * NMC:     单节终止 4.20V, 平台 3.7V
 * ========================================================================= */


/* =========================================================================
 * 初始化 / 反初始化
 * ========================================================================= */
/**
 * @brief 初始化 BQ25710 全功能驱动
 * @param smbus_read   SMBus 读寄存器回调
 * @param smbus_write  SMBus 写寄存器回调
 * @param delay_ms     毫秒延时回调
 * @return BQ25710_ERR_OK 成功, 其他为错误码
 */
bq25710_err_t bq25710_init(bq25710_smbus_read_cb_t  smbus_read,
                            bq25710_smbus_write_cb_t smbus_write,
                            bq25710_delay_ms_cb_t    delay_ms)
{
    if (!smbus_read || !smbus_write || !delay_ms)
    {
        return BQ25710_ERR_NULL_PTR;
    }

    /* 填充回调 */
    g_bq25710_ctx.smbus_read  = smbus_read;
    g_bq25710_ctx.smbus_write = smbus_write;
    g_bq25710_ctx.delay_ms    = delay_ms;

    /* 验证器件 ID */
    BQ25710_DeviceID_t         DevID;         // [0xFF] 器件识别码
    int8_t ret = _reg_read(BQ25710_REG_DEVICE_ID, &DevID.all);
    if (ret != 0) 
    {
        return BQ25710_ERR_I2C;
    }

    if (DevID.maps.DEVICE_ID != BQ25710_DEVICE_ID_VAL) 
    {
        return BQ25710_ERR_DEVICE_ID;
    }

    /* 验证厂商 ID */
    BQ25710_ManufactureID_t    MfrID;         // [0xFE] 厂商识别码
    ret = _reg_read(BQ25710_REG_MANUFACTURE_ID, &MfrID.all);
    if (ret != 0) 
    {
        return BQ25710_ERR_I2C;
    }

    if (MfrID.maps.MANUFACTURE_ID != BQ25710_MFR_ID_VAL) 
    {
        return BQ25710_ERR_DEVICE_ID;
    }
    

    /* 初始化上下文 */
    g_bq25710_ctx.initialized           = 1;
    g_bq25710_ctx.mode                  = BQ25710_MODE_IDLE;
    g_bq25710_ctx.prev_mode             = BQ25710_MODE_IDLE;
    g_bq25710_ctx.prochot_trigger_mask  = BQ25710_PROCHOT_SRC_NONE;
    g_bq25710_ctx.prochot_extended_mode = 0;
    g_bq25710_ctx.wdt_timeout_ms        = 0;
    g_bq25710_ctx.last_kick_ms          = 0;
    g_bq25710_ctx.learn_capacity_mah    = 0.0f;
    g_bq25710_ctx.learn_complete        = 0;
    g_bq25710_ctx.tick_ms               = 0;
    g_bq25710_ctx.tick_valid            = 0;

    /* 清零充电上下文 */
    memset(&g_bq25710_ctx.charge, 0, sizeof(g_bq25710_ctx.charge));

    return BQ25710_ERR_OK;
}

/**
 * @brief  反初始化驱动, 安全关闭所有功能
 * @return BQ25710_ERR_OK 成功
 */
bq25710_err_t bq25710_deinit(void)
{
    if (!g_bq25710_ctx.initialized)
    {
        return BQ25710_ERR_NOT_INIT;
    }

    /* 安全关闭: 先禁止充电, 再关 OTG, 再关各种模式 */
    BQ25710_ChargeOption0_t opt0;
    _reg_read(BQ25710_REG_CHARGE_OPTION_0, &opt0.all);
    opt0.maps.CHRG_INHIBIT = 1;  /* 禁止充电 */
    _reg_write(BQ25710_REG_CHARGE_OPTION_0, opt0.all);

    BQ25710_ChargeOption3_t opt3;
    _reg_read(BQ25710_REG_CHARGE_OPTION_3, &opt3.all);
    opt3.maps.EN_OTG = 0;  /* 关 OTG */
    _reg_write(BQ25710_REG_CHARGE_OPTION_3, opt3.all);

    /* 清除上下文 */
    memset(&g_bq25710_ctx, 0, sizeof(g_bq25710_ctx));
    return BQ25710_ERR_OK;
}

/* =========================================================================
 * 模式管理
 * ========================================================================= */

/**
 * @brief 模式切换合法性表
 *
 * 合法切换:
 *   IDLE          → CHARGING, OTG, PTM, LEARN, PASSTHROUGH
 *   CHARGING      → IDLE, PEAK_POWER_L1, PEAK_POWER_L2, PASSTHROUGH
 *   OTG           → IDLE
 *   PTM           → IDLE, CHARGING
 *   PEAK_POWER_L1 → IDLE, CHARGING
 *   PEAK_POWER_L2 → IDLE, CHARGING
 *   LEARN         → IDLE
 *   PASSTHROUGH   → IDLE, CHARGING
 *
 * @param from       当前模式
 * @param to         目标模式
 * @return 1 合法切换, 0 非法切换
 */
uint8_t bq25710_mode_transition_allowed(bq25710_operation_mode_t from,
                                         bq25710_operation_mode_t to)
{
    /* 同模式切换视为合法 */
    if (from == to) return 1;

    switch (from) {
    case BQ25710_MODE_IDLE: 
        return (to == BQ25710_MODE_CHARGING ||
                to == BQ25710_MODE_OTG ||
                to == BQ25710_MODE_PTM ||
                to == BQ25710_MODE_LEARN ||
                to == BQ25710_MODE_PASSTHROUGH);
    case BQ25710_MODE_CHARGING:
        return (to == BQ25710_MODE_IDLE ||
                to == BQ25710_MODE_PEAK_POWER_L1 ||
                to == BQ25710_MODE_PEAK_POWER_L2 ||
                to == BQ25710_MODE_PASSTHROUGH);
    case BQ25710_MODE_OTG:
        return (to == BQ25710_MODE_IDLE);
    case BQ25710_MODE_PTM:
        return (to == BQ25710_MODE_IDLE ||
                to == BQ25710_MODE_CHARGING);
    case BQ25710_MODE_PEAK_POWER_L1:
    case BQ25710_MODE_PEAK_POWER_L2:
        return (to == BQ25710_MODE_IDLE ||
                to == BQ25710_MODE_CHARGING);
    case BQ25710_MODE_LEARN:
        return (to == BQ25710_MODE_IDLE);
    case BQ25710_MODE_PASSTHROUGH:
        return (to == BQ25710_MODE_IDLE ||
                to == BQ25710_MODE_CHARGING);
    default:
        return 0;
    }
}

/**
 * @brief 内部: 停止当前模式
 */
static bq25710_err_t _mode_stop_current(void)
{
    BQ25710_ChargeOption0_t opt0;
    BQ25710_ChargeOption1_t opt1;
    BQ25710_ChargeOption3_t opt3;

    _reg_read(BQ25710_REG_CHARGE_OPTION_0, &opt0.all);
    _reg_read(BQ25710_REG_CHARGE_OPTION_1, &opt1.all);
    _reg_read(BQ25710_REG_CHARGE_OPTION_3, &opt3.all);

    switch (g_bq25710_ctx.mode) 
    {
    case BQ25710_MODE_CHARGING:
    case BQ25710_MODE_PEAK_POWER_L1:
    case BQ25710_MODE_PEAK_POWER_L2:
        /* 禁止充电 */
        opt0.maps.CHRG_INHIBIT = 1;
        /* 关峰值功率 */
        if (g_bq25710_ctx.mode == BQ25710_MODE_PEAK_POWER_L1 ||
            g_bq25710_ctx.mode == BQ25710_MODE_PEAK_POWER_L2) 
        {
            BQ25710_ChargeOption2_t opt2;
            _reg_read(BQ25710_REG_CHARGE_OPTION_2, &opt2.all);
            opt2.maps.EN_PKPWR_VSYS = 0;
            opt2.maps.EN_PKPWR_IDPM = 0;
            _reg_write(BQ25710_REG_CHARGE_OPTION_2, opt2.all);
        }
        break;
    case BQ25710_MODE_OTG:
        opt3.maps.EN_OTG = 0;                   /* 关 OTG */
        break;
    case BQ25710_MODE_PTM:
        opt1.maps.EN_PTM = 0;                   /* 关 PTM */
        break;
    case BQ25710_MODE_LEARN:
        opt0.maps.EN_LEARN = 0;                 /* 关 LEARN */
        break;
    default:
        break;
    }

    _reg_write(BQ25710_REG_CHARGE_OPTION_0, opt0.all);
    _reg_write(BQ25710_REG_CHARGE_OPTION_1, opt1.all);
    _reg_write(BQ25710_REG_CHARGE_OPTION_3, opt3.all);

    return BQ25710_ERR_OK;
}

/**
 * @brief 内部: 启动新模式
 */
static bq25710_err_t _mode_start_new(bq25710_operation_mode_t mode)
{
    BQ25710_ChargeOption0_t opt0;
    BQ25710_ChargeOption1_t opt1;
    BQ25710_ChargeOption3_t opt3;

    _reg_read(BQ25710_REG_CHARGE_OPTION_0, &opt0.all);
    _reg_read(BQ25710_REG_CHARGE_OPTION_1, &opt1.all);
    _reg_read(BQ25710_REG_CHARGE_OPTION_3, &opt3.all);

    switch (mode) {
    case BQ25710_MODE_CHARGING:
        opt0.maps.EN_LDO  = 1;                  /* 使能 LDO */
        opt0.maps.EN_IDPM = 1;                  /* 使能 IDPM */
        opt0.maps.CHRG_INHIBIT = 0;             /* 使能充电 */
        break;
    case BQ25710_MODE_OTG:
        opt3.maps.EN_OTG = 1;                   /* 使能 OTG */
        break;
    case BQ25710_MODE_PTM:
        opt1.maps.EN_PTM = 1;                   /* 使能 PTM */
        break;
    case BQ25710_MODE_LEARN:
        opt0.maps.EN_LEARN = 1;                 /* 使能 LEARN */
        break;
    case BQ25710_MODE_PASSTHROUGH:
        /* NVDC 功率路径自动管理: 停止充电让硬件自行管理 */
        opt0.maps.CHRG_INHIBIT = 1;             /* 禁止充电 */
        break;
    case BQ25710_MODE_IDLE:
        opt0.maps.CHRG_INHIBIT = 1;             /* 禁止充电 */
        break;
    default:
        break;
    }

    _reg_write(BQ25710_REG_CHARGE_OPTION_0, opt0.all);
    _reg_write(BQ25710_REG_CHARGE_OPTION_1, opt1.all);
    _reg_write(BQ25710_REG_CHARGE_OPTION_3, opt3.all);

    return BQ25710_ERR_OK;
}

bq25710_err_t bq25710_set_mode(bq25710_operation_mode_t mode)
{
    REG_ACCESS_CHECK();

    if (mode > BQ25710_MODE_PASSTHROUGH)
        return BQ25710_ERR_PARAM;

    if (!bq25710_mode_transition_allowed(g_bq25710_ctx.mode, mode))
        return BQ25710_ERR_MODE;

    /* 同模式无操作 */
    if (g_bq25710_ctx.mode == mode)
        return BQ25710_ERR_OK;

    /* 安全序列: 停止当前 → 延迟 10ms → 启动新 */
    _mode_stop_current();
    g_bq25710_ctx.delay_ms(10);
    _mode_start_new(mode);

    g_bq25710_ctx.prev_mode = g_bq25710_ctx.mode;
    g_bq25710_ctx.mode      = mode;

    /* 进入充电模式时重置充电状态机 */
    if (mode == BQ25710_MODE_CHARGING) 
    {
        g_bq25710_ctx.charge.stage = BQ25710_CHG_STAGE_DETECTION;
    }

    return BQ25710_ERR_OK;
}

/**
 * @brief 获取当前操作模式
 * @return 当前操作模式
 */
bq25710_operation_mode_t bq25710_get_mode(void)
{
    return g_bq25710_ctx.mode;
}

