static const struct {
    uint8_t  reg;
    const char *name;
} _reg_map[] = {
    { BQ25710_REG_CHARGE_OPTION_0,  "ChargeOption0"   },
    { BQ25710_REG_CHARGE_OPTION_1,  "ChargeOption1"   },
    { BQ25710_REG_CHARGE_OPTION_2,  "ChargeOption2"   },
    { BQ25710_REG_CHARGE_OPTION_3,  "ChargeOption3"   },
    { BQ25710_REG_PROCHOT_OPTION_0, "ProchotOption0"  },
    { BQ25710_REG_PROCHOT_OPTION_1, "ProchotOption1"  },
    { BQ25710_REG_ADC_OPTION,       "ADCOption"       },
    { BQ25710_REG_CHARGE_CURRENT,   "ChargeCurrent"   },
    { BQ25710_REG_MAX_CHARGE_VOLT,  "MaxChargeVoltage"},
    { BQ25710_REG_INPUT_VOLTAGE,    "InputVoltage"    },
    { BQ25710_REG_MIN_SYS_VOLTAGE,  "MinSystemVoltage"},
    { BQ25710_REG_IN_CURR_HOST,     "IIN_HOST"        },
    { BQ25710_REG_OTG_VOLTAGE,      "OTGVoltage"      },
    { BQ25710_REG_OTG_CURRENT,      "OTGCurrent"      },
    { BQ25710_REG_CHARGER_STATUS,   "ChargerStatus"   },
    { BQ25710_REG_PROCHOT_STATUS,   "ProchotStatus"   },
    { BQ25710_REG_IN_CURR_DPM,      "IIN_DPM (RO)"    },
    { BQ25710_REG_ADC_VBUS_PSYS,    "ADC_VBUS_PSYS"   },
    { BQ25710_REG_ADC_IBAT,         "ADC_IBAT"        },
    { BQ25710_REG_ADC_IIN_CMPIN,    "ADC_IIN_CMPIN"   },
    { BQ25710_REG_ADC_VSYS_VBAT,    "ADC_VSYS_VBAT"   },
    { BQ25710_REG_MANUFACTURE_ID,   "ManufactureID"   },
    { BQ25710_REG_DEVICE_ID,        "DeviceID"        },
};

/**
 * @brief 打印全部寄存器
 */
void bq25710_dump_all_registers(void)
{
    if (!g_bq25710_ctx.initialized) return;

    printf("\n============ BQ25710 Register Dump ============\n");
    printf("| Hex    | 15 14 13 12 11 10 09 08  07 06 05 04 03 02 01 00\n");
    printf("------------------------------------------------------------------------\n");

    int num = sizeof(_reg_map) / sizeof(_reg_map[0]);
    for (int i = 0; i < num; i++) {
        uint16_t val;
        if (_reg_read(_reg_map[i].reg, &val) != 0) {
            printf("%-20s | ERROR\n", _reg_map[i].name);
            continue;
        }

        printf("%-20s | 0x%04X | ", _reg_map[i].name, val);
        for (int j = 15; j >= 0; j--) {
            printf("%c ", (val & (1 << j)) ? '1' : '0');
        }
        printf("\n");
    }
    printf("================================================\n");
}

/**
 * @brief 获取综合系统状态
 * @param status 输出参数, 系统状态结构体
 * @return BQ25710_ERR_OK / BQ25710_ERR_NULL_PTR
 */
bq25710_err_t bq25710_get_system_status(bq25710_system_status_t *status)
{
    REG_ACCESS_CHECK();
    NULL_CHECK(status);

    memset(status, 0, sizeof(bq25710_system_status_t));

    /* 模式与阶段 */
    status->mode      = g_bq25710_ctx.mode;
    status->chg_stage = g_bq25710_ctx.charge.stage;

    /* 适配器 / 电池 */
    BQ25710_ChargerStatus_t    Status;        /**< [0x20] 反馈 AC、ICO、故障锁存信息 */
    _reg_read(BQ25710_REG_CHARGER_STATUS, &Status.all);

    status->adapter_present = Status.maps.AC_STAT;
    status->is_charging     = Status.maps.IN_FCHRG || Status.maps.IN_PCHRG;
    status->is_otg          = Status.maps.IN_OTG;
    status->is_vap          = Status.maps.IN_VAP;
    status->ico_done        = Status.maps.ICO_DONE;

    /* PTM 状态 */
    BQ25710_ChargeOption1_t    Option1;       /**< [0x30] 增益与硬件参数设置 */
    _reg_read(BQ25710_REG_CHARGE_OPTION_1, &Option1.all);
    status->is_ptm = Option1.maps.EN_PTM;

    /* 电池存在检测: ChargerStatus 不直接提供, 通过 ADC_VBAT 判断 */
    bq25710_adc_read_all(&status->adc);
    status->battery_present = (status->adc.vbat_mv > 1000) ? 1 : 0;

    /* 电池参数 */
    status->batt_params = &g_bq25710_ctx.charge.params;

    /* 充电设定 */
    BQ25710_ChargeCurrent_t    ChargeCurrent; /**< [0x14] 电池充电电流目标值 */
    _reg_read(BQ25710_REG_CHARGE_CURRENT, &ChargeCurrent.all);
    status->charge_current_set_ma = (uint16_t)(((ChargeCurrent.all >> 6) & 0x7F) * 64);

    BQ25710_MaxChargeVoltage_t MaxChargeVolt; /**< [0x15] 电池充电电压目标 */
    _reg_read(BQ25710_REG_MAX_CHARGE_VOLT, &MaxChargeVolt.all);
    status->charge_voltage_set_mv = (uint16_t)(((MaxChargeVolt.all >> 3) & 0xFFF) * 8);

    /* 输入电流限制 */
    BQ25710_IN_CURR_HOST_t     InCurrHost;    /**< [0x3F] 适配器端输入电流限制 */
    _reg_read(BQ25710_REG_IN_CURR_HOST, &InCurrHost.all);
    status->input_current_limit_ma = (uint16_t)(((InCurrHost.all >> 8) & 0x7F) * 50);

    /* 故障 */
    bq25710_fault_check(&status->fault);

    /* 检查是否有活动故障 */
    uint16_t *f = (uint16_t *)&status->fault;
    status->fault_active = (*f != 0) ? 1 : 0;

    /* 运行时间 */
    status->uptime_ms      = g_bq25710_ctx.tick_ms;
    status->chg_elapsed_ms = g_bq25710_ctx.charge.total_elapsed_ms;
    status->wdt_timeout_ms = g_bq25710_ctx.wdt_timeout_ms;
    status->last_kick_ms   = g_bq25710_ctx.last_kick_ms;

    return BQ25710_ERR_OK;
}

/**
 * @brief 打印格式化的 ASCII 状态报告
 */
void bq25710_print_status_report(void)
{
    if (!g_bq25710_ctx.initialized) {
        printf("BQ25710: 驱动未初始化\n");
        return;
    }

    bq25710_system_status_t st;
    bq25710_get_system_status(&st);

    printf("\n============ BQ25710 System Status ============\n");
    printf("  Mode:          %s\n", bq25710_mode_names_en[st.mode]);
    printf("  Charge Stage:  %s\n", _chg_stage_names_en[st.chg_stage]);

    printf("  AC Adapter:    %s\n", st.adapter_present ? "ONLINE" : "OFFLINE");
    printf("  Battery:       %s\n", st.battery_present ? "PRESENT" : "MISSING");
    printf("  Charging:      %s\n", st.is_charging ? "YES" : "NO");
    printf("  OTG Active:    %s\n", st.is_otg ? "YES" : "NO");
    printf("  VAP Active:    %s\n", st.is_vap ? "YES" : "NO");
    printf("  PTM Active:    %s\n", st.is_ptm ? "YES" : "NO");
    printf("  ICO Done:      %s\n", st.ico_done ? "YES" : "NO");

    if (st.battery_present && (st.batt_params != NULL)) {
        printf("  Chemistry:     %s, %dS\n",
               st.batt_params->chemistry_name,
               battery_cells_value(st.batt_params->cells));
    }

    printf("  --- ADC Readings ---\n");
    printf("  VBUS:  %5u mV\n", st.adc.vbus_mv);
    printf("  VSYS:  %5u mV\n", st.adc.vsys_mv);
    printf("  VBAT:  %5u mV\n", st.adc.vbat_mv);
    printf("  ICHG:  %5d mA\n", (int)st.adc.ichg_ma);
    printf("  IDCHG: %5d mA\n", (int)st.adc.idchg_ma);
    printf("  IIN:   %5d mA\n", (int)st.adc.iin_ma);
    printf("  PSYS:  %5d mW\n", (int)st.adc.psys_mw);
    printf("  CMPIN: %5u mV\n", st.adc.cmpin_mv);

    printf("  --- Settings ---\n");
    printf("  VREG Set:    %5u mV\n", st.charge_voltage_set_mv);
    printf("  ICHG Set:    %5u mA\n", st.charge_current_set_ma);
    printf("  IIN Limit:   %5u mA\n", st.input_current_limit_ma);
    printf("  WDT Timeout: %5u ms\n", st.wdt_timeout_ms);

    printf("  --- Faults ---\n");
    if (st.fault_active) {
        char fault_str[256];
        bq25710_fault_get_detail(&st.fault, fault_str, sizeof(fault_str));
        printf("  ACTIVE: %s\n", fault_str);
    } else {
        printf("  CLEAR (no faults)\n");
    }

    printf("  Uptime:       %u ms\n", st.uptime_ms);
    printf("================================================\n");
}
